insert into build_presets (
  id, slug, name, audience, tagline, rationale, highlights, items,
  status, sort_order
) values
  ('starter-1080p', 'starter-1080p', 'Ascent 1080p', 'gaming', 'A first custom build for high-refresh 1080p play.', 'Spends where frame rate comes from and nowhere else: a current six-core processor, a card with enough memory to age well, and a board on the AM5 socket so the processor can be replaced later without changing anything else.', array['AM5 platform, so a processor upgrade does not mean a new board', '16 GB of memory in two modules, leaving two slots free', 'Air cooled, which keeps the part count and the noise down'], '[{"category":"cpu","component_id":"cpu-amd-ryzen-5-7600x","quantity":1},{"category":"motherboard","component_id":"mb-asus-rog-strix-b850-f","quantity":1},{"category":"cooler","component_id":"cool-deepcool-ak620-g2","quantity":1},{"category":"ram","component_id":"ram-xpg-lancer-blade-16gb-ddr5-5600","quantity":1},{"category":"gpu","component_id":"gpu-msi-rtx-5060-ti-16g","quantity":1},{"category":"storage","component_id":"ssd-kingston-nv3-1tb","quantity":1},{"category":"psu","component_id":"psu-deepcool-pn650m","quantity":1},{"category":"case","component_id":"case-nzxt-h5-flow","quantity":1},{"category":"os","component_id":"os-windows-11-home","quantity":1}]'::jsonb, 'published', 10),
  ('gaming-1440p', 'gaming-1440p', 'Meridian 1440p', 'gaming', 'High-refresh 1440p with room to grow.', 'The configuration most gaming customers end up at. A cache-heavy gaming processor, a 16 GB card sized for 1440p, and a power supply with enough headroom that a bigger card later does not mean a second purchase.', array['32 GB of low-latency DDR5-6000 CL30', '2 TB NVMe boot drive, no secondary drive needed on day one', '850 W supply leaves headroom for a larger card later'], '[{"category":"cpu","component_id":"cpu-amd-ryzen-7-9800x3d","quantity":1},{"category":"motherboard","component_id":"mb-asus-rog-strix-b850-f","quantity":1},{"category":"cooler","component_id":"cool-arctic-liquid-freezer-iii-360","quantity":1},{"category":"ram","component_id":"ram-teamgroup-vulcan-32gb-ddr5-6000","quantity":1},{"category":"gpu","component_id":"gpu-sapphire-rx-9070-xt","quantity":1},{"category":"storage","component_id":"ssd-wd-black-sn850x-2tb","quantity":1},{"category":"psu","component_id":"psu-deepcool-pn850m","quantity":1},{"category":"case","component_id":"case-corsair-frame-4000d-rs","quantity":1},{"category":"os","component_id":"os-windows-11-home","quantity":1}]'::jsonb, 'published', 20),
  ('gaming-4k', 'gaming-4k', 'Summit 4K', 'gaming', 'Built around the fastest card the budget allows.', 'At 4K the graphics card sets the ceiling, so the rest of the build exists to keep it fed and cool: a 360 mm radiator, a case with real clearance for a 340 mm card, and a supply sized with headroom above the estimated draw.', array['Dual-chamber case with room for a long card and a 360 mm radiator', '1000 W supply against an estimated draw well under it', '6 TB of NVMe storage across two drives'], '[{"category":"cpu","component_id":"cpu-amd-ryzen-7-9800x3d","quantity":1},{"category":"motherboard","component_id":"mb-msi-mag-x870-tomahawk","quantity":1},{"category":"cooler","component_id":"cool-arctic-liquid-freezer-iii-360","quantity":1},{"category":"ram","component_id":"ram-teamgroup-vulcan-32gb-ddr5-6000","quantity":1},{"category":"gpu","component_id":"gpu-gigabyte-rtx-5080-gaming-oc","quantity":1},{"category":"storage","component_id":"ssd-wd-black-sn850x-2tb","quantity":1},{"category":"storage","component_id":"ssd-wd-black-sn7100-4tb","quantity":1},{"category":"psu","component_id":"psu-deepcool-pn1000m","quantity":1},{"category":"case","component_id":"case-lian-li-o11d-evo-rgb","quantity":1},{"category":"os","component_id":"os-windows-11-pro","quantity":1}]'::jsonb, 'published', 30),
  ('creator-workstation', 'creator-workstation', 'Studio 16C', 'workstation', 'Rendering, editing and compile jobs that scale with cores.', 'Sixteen cores and 64 GB of memory, because export and build times respond to both. Storage is split so the project drive is not competing with the operating system.', array['16-core processor for export, render and compile work', '64 GB of DDR5 with two slots still free', 'Separate operating system and project drives'], '[{"category":"cpu","component_id":"cpu-amd-ryzen-9-9950x","quantity":1},{"category":"motherboard","component_id":"mb-msi-mag-x870-tomahawk","quantity":1},{"category":"cooler","component_id":"cool-arctic-liquid-freezer-iii-360","quantity":1},{"category":"ram","component_id":"ram-teamgroup-delta-64gb-ddr5-6000","quantity":1},{"category":"gpu","component_id":"gpu-msi-rtx-5060-ti-16g","quantity":1},{"category":"storage","component_id":"ssd-wd-black-sn850x-2tb","quantity":1},{"category":"storage","component_id":"ssd-wd-black-sn7100-4tb","quantity":1},{"category":"psu","component_id":"psu-deepcool-pn1000m","quantity":1},{"category":"case","component_id":"case-corsair-frame-4000d-rs","quantity":1},{"category":"os","component_id":"os-windows-11-pro","quantity":1}]'::jsonb, 'published', 40),
  ('engineering-workstation', 'engineering-workstation', 'Atlas 24C', 'workstation', 'Large datasets, simulation and heavy virtualisation.', 'Core count and memory capacity first, on a platform with five M.2 slots so storage can be added without replacing anything. A job that fits in memory finishes; one that spills to disk takes an order of magnitude longer.', array['24 cores on the LGA1851 platform', '64 GB of DDR5, expandable to 256 GB on this board', 'Five M.2 slots on the board for future storage'], '[{"category":"cpu","component_id":"cpu-intel-core-ultra-9-285k","quantity":1},{"category":"motherboard","component_id":"mb-msi-mpg-z890-carbon","quantity":1},{"category":"cooler","component_id":"cool-arctic-liquid-freezer-iii-360","quantity":1},{"category":"ram","component_id":"ram-teamgroup-delta-64gb-ddr5-6000","quantity":1},{"category":"gpu","component_id":"gpu-sapphire-rx-9070-xt","quantity":1},{"category":"storage","component_id":"ssd-wd-black-sn850x-2tb","quantity":1},{"category":"storage","component_id":"ssd-wd-black-sn7100-4tb","quantity":1},{"category":"psu","component_id":"psu-gigabyte-ud1300gm","quantity":1},{"category":"case","component_id":"case-lian-li-o11d-evo-rgb","quantity":1},{"category":"os","component_id":"os-windows-11-pro","quantity":1}]'::jsonb, 'published', 50),
  ('compact-itx', 'compact-itx', 'Transit ITX', 'gaming', 'A mini-ITX board in a case that still takes a full-size card.', 'Small-form-factor builds are constrained by clearance before anything else. This pairs a mini-ITX board with a case that accepts it, so the board footprint shrinks without forcing compromises on the card or the cooler.', array['Mini-ITX board with Wi-Fi 7 and a PCIe 5.0 graphics slot', 'Two memory slots, so one 32 GB kit fills it', 'Card and cooler checked against the case clearance figures'], '[{"category":"cpu","component_id":"cpu-amd-ryzen-7-7800x3d","quantity":1},{"category":"motherboard","component_id":"mb-asus-rog-strix-b850-i","quantity":1},{"category":"cooler","component_id":"cool-deepcool-ak620-g2","quantity":1},{"category":"ram","component_id":"ram-teamgroup-vulcan-32gb-ddr5-6000","quantity":1},{"category":"gpu","component_id":"gpu-msi-rtx-5060-ti-16g","quantity":1},{"category":"storage","component_id":"ssd-wd-black-sn850x-1tb","quantity":1},{"category":"psu","component_id":"psu-deepcool-pn750m","quantity":1},{"category":"case","component_id":"case-nzxt-h5-flow","quantity":1},{"category":"os","component_id":"os-windows-11-home","quantity":1}]'::jsonb, 'published', 60)
